#!/usr/bin/env python3
"""Stage 4-7 Temporal Ego-centric World Model & Split-Screen Demo Runner using v1 kernel outputs."""

import base64
import json
import os
import shutil
import subprocess
import sys
import urllib.request
import zipfile
import zlib
from pathlib import Path

TRACK_UTILS_B64 = ''
WORLD_MODEL_B64 = ''
WORLD_VIS_B64 = ''
VALIDATION_B64 = ''
DEMO_SEQS = ["0015", "0019"]
S3_LABEL_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_label_2.zip"
S3_CALIB_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_calib.zip"
S3_OXTS_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_oxts.zip"
S3_IMAGE_URL = "https://s3.eu-central-1.amazonaws.com/avg-kitti/data_tracking_image_2.zip"


def run(cmd, check=True):
    print(f"[CMD] {' '.join(map(str, cmd))}", flush=True)
    return subprocess.run(cmd, check=check)


def download_file(url: str, dst: Path) -> None:
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists() and dst.stat().st_size > 0:
        return
    curl = shutil.which("curl")
    if curl:
        run([curl, "-L", "-C", "-", "--retry", "5", "--retry-delay", "5", "-o", str(dst), url])
    else:
        with urllib.request.urlopen(url) as resp, open(dst, "wb") as out:
            shutil.copyfileobj(resp, out)


def find_trajectories_csvs() -> dict[str, Path]:
    found: dict[str, Path] = {}
    input_root = Path("/kaggle/input")
    print("[INPUT TREE]", [str(p) for p in sorted(input_root.glob("*"))], flush=True)
    for p in sorted(input_root.rglob("trajectories.csv")):
        parent_name = p.parent.name
        if parent_name.startswith("track_"):
            seq = parent_name.replace("track_", "", 1)
            found[seq] = p
    print("[FOUND TRAJECTORIES]", {k: str(v) for k, v in found.items()}, flush=True)
    return found


def find_training_image_dir() -> Path | None:
    candidates = [
        Path("/kaggle/input/datasets/leducnhuan/kitti-tracking/kitti_tracking/training/image_02"),
        Path("/kaggle/input/datasets/leducnhuan/kitti-tracking/training/image_02"),
        Path("/kaggle/input/kitti-tracking/kitti_tracking/training/image_02"),
        Path("/kaggle/input/kitti-tracking/training/image_02"),
    ]
    for cand in candidates:
        if cand.is_dir() and (cand / "0015").is_dir() and (cand / "0019").is_dir():
            print(f"[FOUND TRAINING IMAGE_02] {cand}", flush=True)
            return cand
    return None


def find_seq_txt(root: Path, seq: str, split: str = "training") -> Path | None:
    if not root.exists():
        return None
    split_matches = [p for p in sorted(root.rglob(f"{seq}.txt")) if split in p.parts]
    if split_matches:
        return split_matches[0]
    matches = sorted(root.rglob(f"{seq}.txt"))
    return matches[0] if matches else None


def main() -> None:
    work_dir = Path("/kaggle/working")
    src_dir = work_dir / "src"
    src_dir.mkdir(parents=True, exist_ok=True)
    (src_dir / "__init__.py").write_text("", encoding="utf-8")
    (src_dir / "track_utils.py").write_bytes(zlib.decompress(base64.b64decode(TRACK_UTILS_B64)))
    (src_dir / "world_model.py").write_bytes(zlib.decompress(base64.b64decode(WORLD_MODEL_B64)))
    (src_dir / "world_visualizer.py").write_bytes(zlib.decompress(base64.b64decode(WORLD_VIS_B64)))
    (src_dir / "validation_experiments.py").write_bytes(zlib.decompress(base64.b64decode(VALIDATION_B64)))
    sys.path.insert(0, str(src_dir))

    from validation_experiments import run_all_validations
    from world_visualizer import generate_world_model_demo

    traj_map = find_trajectories_csvs()
    for seq in DEMO_SEQS:
        assert seq in traj_map, f"Missing trajectories.csv for seq {seq} under /kaggle/input"

    tmp_dir = Path("/tmp/world_model_prep")
    tmp_dir.mkdir(parents=True, exist_ok=True)

    label_zip = tmp_dir / "data_tracking_label_2.zip"
    calib_zip = tmp_dir / "data_tracking_calib.zip"
    oxts_zip = tmp_dir / "data_tracking_oxts.zip"
    download_file(S3_LABEL_URL, label_zip)
    download_file(S3_CALIB_URL, calib_zip)
    download_file(S3_OXTS_URL, oxts_zip)

    with zipfile.ZipFile(label_zip, "r") as zf:
        zf.extractall(tmp_dir / "labels")
    with zipfile.ZipFile(calib_zip, "r") as zf:
        zf.extractall(tmp_dir / "calib")
    with zipfile.ZipFile(oxts_zip, "r") as zf:
        zf.extractall(tmp_dir / "oxts")

    img_dir = find_training_image_dir()
    image_zip = None
    if img_dir is None:
        print("[DL] Downloading S3 image archive...", flush=True)
        image_zip = tmp_dir / "data_tracking_image_2.zip"
        download_file(S3_IMAGE_URL, image_zip)

    out_dir = work_dir / "world_outputs"
    out_dir.mkdir(parents=True, exist_ok=True)

    summaries = {}
    validations = {}
    for seq in DEMO_SEQS:
        seq_dir = tmp_dir / f"seq_{seq}"
        seq_dir.mkdir(parents=True, exist_ok=True)
        if img_dir is not None:
            for p in sorted((img_dir / seq).glob("*.png")):
                shutil.copy2(p, seq_dir / p.name)
        else:
            prefix = f"training/image_02/{seq}/"
            with zipfile.ZipFile(image_zip, "r") as zf:
                for entry in sorted(zf.namelist()):
                    if entry.startswith(prefix) and entry.endswith(".png"):
                        (seq_dir / Path(entry).name).write_bytes(zf.read(entry))

        traj_csv = traj_map[seq]
        calib_file = find_seq_txt(tmp_dir / "calib", seq)
        label_file = find_seq_txt(tmp_dir / "labels", seq)
        oxts_file = find_seq_txt(tmp_dir / "oxts", seq)
        print(f"[SEQ {seq}] calib={calib_file} label={label_file} oxts={oxts_file}", flush=True)

        # Staged 5-second+ demo (80 frames = 8.0s @ 10 Hz)
        staged_out = out_dir / f"world_model_{seq}_staged"
        sum_staged = generate_world_model_demo(
            images_dir=seq_dir,
            trajectories_csv=traj_csv,
            output_dir=staged_out,
            calib_file=calib_file,
            label_file=label_file,
            oxts_file=oxts_file,
            seq_id=seq,
            fps=10.0,
            max_frames=80,
            staged_demo=True,
        )
        summaries[f"{seq}_staged"] = sum_staged
        print(f"[WORLD STAGED {seq}]", json.dumps(sum_staged, indent=2), flush=True)

        # Full-sequence evaluation against KITTI 3D GT (eval JSON + timeline only)
        full_out = out_dir / f"world_model_{seq}_full"
        sum_full = generate_world_model_demo(
            images_dir=seq_dir,
            trajectories_csv=traj_csv,
            output_dir=full_out,
            calib_file=calib_file,
            label_file=label_file,
            oxts_file=oxts_file,
            seq_id=seq,
            fps=10.0,
            max_frames=None,
            staged_demo=False,
        )
        summaries[f"{seq}_full"] = sum_full
        print(f"[WORLD FULL {seq}]", json.dumps(sum_full, indent=2), flush=True)

        # RQ1-RQ3 Empirical Validation Experiments
        assert calib_file is not None and label_file is not None and oxts_file is not None, (
            f"Missing calib/label/oxts for validation on seq {seq}"
        )
        val_res = run_all_validations(
            seq_id=seq,
            trajectories_csv=traj_csv,
            calib_file=calib_file,
            oxts_file=oxts_file,
            label_file=label_file,
            fps=10.0,
        )
        validations[seq] = val_res
        (out_dir / f"validation_{seq}.json").write_text(json.dumps(val_res, indent=2), encoding="utf-8")
        print(f"[VALIDATION RQ1-RQ3 {seq}]", json.dumps(val_res, indent=2), flush=True)

    if image_zip is not None and image_zip.exists():
        image_zip.unlink()

    (out_dir / "world_model_all_summaries.json").write_text(json.dumps(summaries, indent=2), encoding="utf-8")
    (out_dir / "validation_rq1_rq2_rq3.json").write_text(json.dumps(validations, indent=2), encoding="utf-8")
    print("[DONE] Stage 4-7 World Model & RQ1-RQ3 Validation outputs ready in", out_dir, flush=True)


if __name__ == "__main__":
    main()
